+    Texture(Texture &&other) AI_NO_EXCEPT = default;

-        return *this;
-    }
+    Texture &operator=(Texture &&other) AI_NO_EXCEPT = default;

     //! Specifies the blend factor for the texture
     ai_real mTextureBlend;
@@ -436,83 +395,13 @@ struct Material {
         // empty
     }

